def selectie_minim(L):
    n = len(L)
    for i in range(n):
        minim = i
        for j in range(i + 1, n):
            if L[j] < L[minim]:
                minim = j
        L[i], L[minim] = L[minim], L[i]
    return L

print(selectie_minim([5, 2, 9, 1]))

