def bubble(L):
    n = len(L)
    for i in range(n):
        for j in range(0, n - i - 1):
            if L[j] > L[j + 1]:   # interschimbă dacă sunt în ordine greșită
                L[j], L[j + 1] = L[j + 1], L[j]
    return L

print(bubble([4, 2, 7, 1]))

